export const APP_VERSION="1.0.0",DATA_SCHEMA_VERSION=2,DB_NAME="seb-navigator-local",STORE="settings",SALES_KEY="sales-records",DATASET_KEY="commission-dataset",RAW_WORKBOOK_KEY="commission-workbook",AUTH_KEY="authorized-profile",SCHEMA_KEY="data-schema-version";
export const normalize=v=>String(v??"").toUpperCase().replace(/[^A-Z0-9А-ЯЁ]/g,"");
export const articleLabel=p=>{const parts=[];if(p?.sulpakArticle)parts.push(`S:${p.sulpakArticle}`);if(p?.mechtaArticle)parts.push(`M:${p.mechtaArticle}`);return parts.join(" ")||p?.article||""};
const moneyFormatter=new Intl.NumberFormat("ru-RU",{maximumFractionDigits:0}),percentFormatter=new Intl.NumberFormat("ru-RU",{style:"percent",maximumFractionDigits:1});
export const formatMoney=v=>`${moneyFormatter.format(Number(v)||0)} ₸`;
export const formatPercent=v=>percentFormatter.format(Number(v)||0);
export const escapeHtml=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
export const saleDate=s=>new Date(s.soldAt||s.createdAt),saleSalary=s=>Number(s.price)*Number(s.quantity)*Number(s.belowRate??s.rate),salePlanSalary=s=>Number(s.price)*Number(s.quantity)*Number(s.atPlanRate??s.rate),saleRevenue=s=>Number(s.price)*Number(s.quantity);
export const makeId=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
let dbPromise=null;
export function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error("Локальное хранилище недоступно. Откройте приложение в обычном режиме браузера."));return}const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE)};r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>{db.close();dbPromise=null};resolve(db)};r.onerror=()=>{dbPromise=null;reject(Error("Не удалось открыть локальное хранилище."))};r.onblocked=()=>{dbPromise=null;reject(Error("Закройте другие вкладки приложения и повторите попытку."))}});return dbPromise}
export async function loadSetting(key){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readonly"),r=tx.objectStore(STORE).get(key);r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error)})}
export async function saveSetting(key,value){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite"),store=tx.objectStore(STORE);if(key===DATASET_KEY&&value?.rawWorkbook instanceof ArrayBuffer){const compact={...value};store.put(value.rawWorkbook,RAW_WORKBOOK_KEY);delete compact.rawWorkbook;store.put(compact,key)}else store.put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
export async function deleteSetting(key){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,"readwrite");tx.objectStore(STORE).delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
export async function ensureDataSchema(){const stored=Number(await loadSetting(SCHEMA_KEY).catch(()=>0))||0;if(stored>DATA_SCHEMA_VERSION)throw Error("Данные созданы более новой версией приложения. Обновите приложение.");let version=stored;while(version<DATA_SCHEMA_VERSION){version+=1;if(version===1){const sales=await loadSetting(SALES_KEY).catch(()=>null);if(sales!==null&&!Array.isArray(sales))await saveSetting(SALES_KEY,[])}if(version===2){const dataset=await loadSetting(DATASET_KEY).catch(()=>null);if(dataset?.rawWorkbook instanceof ArrayBuffer){await saveSetting(RAW_WORKBOOK_KEY,dataset.rawWorkbook);const compact={...dataset};delete compact.rawWorkbook;await saveSetting(DATASET_KEY,compact)}}await saveSetting(SCHEMA_KEY,version)}return version}
const validSale=s=>s&&typeof s==="object"&&String(s.id||"")&&String(s.article||"")&&Number.isFinite(Number(s.price))&&Number(s.price)>0&&Number.isInteger(Number(s.quantity))&&Number(s.quantity)>0&&Number.isFinite(saleDate(s).getTime());
export async function loadSales(){const stored=await loadSetting(SALES_KEY).catch(()=>[]),sales=Array.isArray(stored)?stored:[],cut=Date.now()-365*86400000,kept=sales.filter(validSale).map(s=>({...s,price:Number(s.price),quantity:Number(s.quantity),soldAt:s.soldAt||s.createdAt,createdAt:s.createdAt||s.soldAt,updatedAt:s.updatedAt||s.createdAt||s.soldAt,returned:Boolean(s.returned)})).filter(s=>saleDate(s).getTime()>=cut).slice(-20000);if(JSON.stringify(kept)!==JSON.stringify(sales))await saveSetting(SALES_KEY,kept).catch(()=>{});return kept}
export const saveSales=sales=>{if(!Array.isArray(sales)||!sales.every(validSale))return Promise.reject(Error("История продаж содержит некорректные данные."));return saveSetting(SALES_KEY,sales)};
export function buildRelation(products,commissions){const keys=new Map;for(const p of Array.isArray(products)?products:[]){if(!p?.article)continue;const set=new Set([normalize(p.commCode),...(Array.isArray(p.modelKeys)?p.modelKeys:[]).map(normalize)]);set.delete("");for(const k of set){if(!keys.has(k))keys.set(k,[]);keys.get(k).push(p)}}const relation=new Map,unmatched=[];for(const c of Array.isArray(commissions)?commissions:[]){if(!c?.commCode)continue;const m=keys.get(normalize(c.normalizedCode||c.commCode))||[];if(m.length!==1){unmatched.push(c);continue}relation.set(m[0].article,c)}return{relation,unmatched}}
async function fetchJson(path,label){const response=await fetch(path);if(!response.ok)throw Error(`Не удалось загрузить ${label}. Код ${response.status}.`);try{return await response.json()}catch{throw Error(`${label} повреждён или имеет неверный формат.`)}}
const CATALOG_PATH="./data/idx-7f2ae1.bin",CATALOG_OBFUSCATION_KEY=new TextEncoder().encode("seb-navigator-2026-catalog-key");
function deobfuscate(base64){const binary=atob(base64),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i)^CATALOG_OBFUSCATION_KEY[i%CATALOG_OBFUSCATION_KEY.length];return new TextDecoder("utf-8").decode(bytes)}
async function fetchCatalog(){const response=await fetch(CATALOG_PATH);if(!response.ok)throw Error(`Не удалось загрузить каталог. Код ${response.status}.`);try{return JSON.parse(deobfuscate(await response.text()))}catch{throw Error("Каталог повреждён или имеет неверный формат.")}}
export async function requireAuthorization(){await ensureDataSchema();const profile=await loadSetting(AUTH_KEY).catch(()=>null);let dataset=null;if(profile?.firstName&&profile?.lastName&&!(Number(profile.validRows)>0))dataset=await loadSetting(DATASET_KEY).catch(()=>null);if(!profile?.firstName||!profile?.lastName||(!(Number(profile.validRows)>0)&&(!Array.isArray(dataset?.rows)||!dataset.rows.length))){if(!location.pathname.endsWith("/auth.html"))location.replace("./auth.html");const error=Error("AUTH_REQUIRED");error.code="AUTH_REQUIRED";throw error}return{profile,dataset}}
function attachIdentity(profile){const head=document.querySelector(".app-head");if(!head||head.querySelector(".identity-button"))return;const button=document.createElement("button");button.type="button";button.className="identity-button";button.title="Выйти и сменить файл комиссий";button.textContent=`${profile.firstName[0]||""}${profile.lastName[0]||""}`.toUpperCase();button.onclick=async()=>{if(!confirm(`Выйти из профиля ${profile.firstName} ${profile.lastName}? История продаж останется на устройстве.`))return;await Promise.all([deleteSetting(AUTH_KEY),deleteSetting(DATASET_KEY),deleteSetting(RAW_WORKBOOK_KEY)]);location.replace("./auth.html")};head.append(button)}
export async function loadContext(){const{profile,dataset:authorizedDataset}=await requireAuthorization(),[dataset,products,sales]=await Promise.all([authorizedDataset||loadSetting(DATASET_KEY),fetchCatalog(),loadSales()]);if(!Array.isArray(products)||!products.length)throw Error("Каталог пуст или повреждён.");const{relation,unmatched}=buildRelation(products,dataset.rows);for(const s of sales){const c=relation.get(s.article);s.belowRate=Number(s.belowRate??c?.belowPlan??s.rate??0);s.atPlanRate=Number(s.atPlanRate??c?.atPlan??s.rate??0);s.rate=s.belowRate}attachIdentity(profile);return{products,dataset,relation,unmatched,sales,profile}}
export async function loadHistoryContext(){const{profile}=await requireAuthorization(),sales=await loadSales(),rawWorkbook={then(resolve,reject){loadSetting(RAW_WORKBOOK_KEY).then(resolve,reject)}};attachIdentity(profile);return{sales,profile,dataset:{rawWorkbook}}}
export function applyTheme(){const root=document.documentElement,dark=localStorage.getItem("seb-theme-dark")!=="0",raw=Number(localStorage.getItem("seb-theme-hue")),hue=Number.isFinite(raw)&&raw>=0&&raw<=360?Math.round(raw):216,size=localStorage.getItem("seb-theme-size")||"medium",atmosphere=localStorage.getItem("seb-theme-atmosphere")||"aurora",surface=localStorage.getItem("seb-theme-surface")||"solid";root.dataset.theme=dark?"dark":"light";root.dataset.size=size;root.dataset.atmosphere=atmosphere;root.dataset.surface=surface;root.style.setProperty("--accent-hue",String(hue));root.style.setProperty("--accent",`hsl(${hue} 100% 59%)`);document.querySelector('meta[name="theme-color"]')?.setAttribute("content",`hsl(${hue} 100% 59%)`)}
export function initPageState(page,getState,applyState){applyTheme();const key=`seb-page-${page}`;let saved=null;try{saved=JSON.parse(sessionStorage.getItem(key)||"null")}catch{sessionStorage.removeItem(key)}if(saved&&typeof saved==="object")applyState?.(saved);requestAnimationFrame(()=>scrollTo(0,Number(saved?.scrollY)||0));addEventListener("pagehide",()=>{try{sessionStorage.setItem(key,JSON.stringify({...getState?.(),scrollY:scrollY}))}catch{}})}
export function enableDialogBackdropClose(...dialogs){for(const dialog of dialogs.filter(Boolean)){if(dialog.dataset.backdropClose==="1")continue;dialog.dataset.backdropClose="1";dialog.addEventListener("pointerdown",e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()})}}
export function showFatal(error){if(error?.code==="AUTH_REQUIRED")return;console.error(error);const main=document.querySelector("main")||document.body,box=document.createElement("section");box.className="fatal-error";box.innerHTML=`<strong>Не удалось открыть раздел</strong><p>${escapeHtml(error?.message||"Произошла неизвестная ошибка.")}</p><button type="button">Повторить</button>`;box.querySelector("button").onclick=()=>location.reload();main.prepend(box)}
export const startOfMonth=d=>new Date(d.getFullYear(),d.getMonth(),1),endOfMonth=d=>new Date(d.getFullYear(),d.getMonth()+1,0,23,59,59,999),inDateRange=(s,f,t)=>{const d=saleDate(s);return d>=f&&d<=t};
function showUpdateReady(){if(document.querySelector(".update-ready"))return;const notice=document.createElement("div");notice.className="update-ready";notice.innerHTML='<span>Доступна новая версия</span><button type="button">Обновить</button>';notice.querySelector("button").onclick=()=>location.reload();document.body.append(notice)}
if("serviceWorker" in navigator)addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").then(registration=>{if(registration.waiting)showUpdateReady();registration.addEventListener("updatefound",()=>{const worker=registration.installing;worker?.addEventListener("statechange",()=>{if(worker.state==="installed"&&navigator.serviceWorker.controller)showUpdateReady()})});return registration.update()}).catch(()=>{}));
